export function registerPartTwo(themes,lessons,words,activities,bookPages){
for(const t of partTwo){for(let k=0;k<t.vocab.length;k+=5){const id=lessons.length;const l={id,part:2,title:t.title+" · слова "+(k/5+1),chapter:t.chapter,icon:t.icon,words:t.vocab.slice(k,k+5).map(([en,ru],j)=>({id:`${id}-${j}`,en,ru,icon:t.icon,speech:en,lesson:id,part:2}))};lessons.push(l);words.push(...l.words);t.ids.push(id);}activities[t.id]=t.activities;bookPages[t.id]=t.pages;themes.push(t);}
}

